def __post_init__(self):
    digits = self.isbn.replace("-", "").replace(" ", "")
    if len(digits) != 13 or not digits.isdigit():
        raise ValueError(f"an ISBN-13 has 13 digits: {self.isbn!r}")
    check = (10 - sum(int(c) * (1 if i % 2 == 0 else 3) for i, c in enumerate(digits[:12])) % 10) % 10
    if check != int(digits[12]):
        raise ValueError(f"{self.isbn!r}: the check digit should be {check}")
    self.isbn = digits
